// Dynamic programming + Dichotomy.
func lengthOfLIS(nums []int) int {
	tails := make([]int, len(nums))
	res := 0
	for _, num := range nums {
		i, j := 0, res
		for i < j {
			m := (i + j) / 2
			if tails[m] < num { // 如果要求非严格递增，将此行 '<' 改为 '<=' 即可
				i = m + 1
			} else {
				j = m
			}
		}
		tails[i] = num
		if j == res {
			res++
		}
	}
	return res
}

