func lengthOfLIS(nums []int) int {
	if len(nums) == 0 {
		return 0
	}
	dp := make([]int, len(nums))
	for i := range nums {
		dp[i] = 1
		for j := 0; j < i; j++ {
			if nums[i] > nums[j] && dp[j]+1 > dp[i] {
				dp[i] = dp[j] + 1
			}
		}
	}
	maxL := 0
	for _, v := range dp {
		if v > maxL {
			maxL = v
		}
	}
	return maxL
}

func lengthOfLIS(nums []int) int {
	d := []int{}
	for _, n := range nums {
		if len(d) == 0 || n > d[len(d)-1] {
			d = append(d, n)
		} else {
			l, r := 0, len(d)-1
			loc := r
			for l <= r {
				mid := (l + r) / 2
				if d[mid] >= n {
					loc = mid
					r = mid - 1
				} else {
					l = mid + 1
				}
			}
			d[loc] = n
		}
	}
	return len(d)
}
